import type { AnalyticsEvent, ContentExposureEvent } from './types';

/** Field separator for coalescing keys — never present in content keys. */
const KEY_SEPARATOR = '';

/**
 * Builds the coalescing key for a content-exposure event. Two exposures of the
 * same node, page, locale, experiment, and variant collapse into one event with
 * an incremented `count`.
 */
const exposureKey = (event: ContentExposureEvent): string =>
  [
    event.url,
    event.dictionaryKey,
    event.keyPath,
    event.locale,
    event.experimentKey ?? '',
    event.variant ?? '',
  ].join(KEY_SEPARATOR);

/**
 * A bounded, coalescing in-memory buffer for analytics events.
 *
 * - `page_view` and `conversion` events are appended verbatim (they are rare
 *   and valuable — they are never evicted while exposures remain).
 * - `content_exposure` events are deduplicated by page/node/locale/variant with
 *   a running `count`, keeping the highest-volume signal cheap.
 * - When the total number of stored events exceeds `max`, the **oldest
 *   exposures** are evicted first (analytics is lossy by design; exposures are
 *   the expendable signal). Discrete events are only dropped once no exposures
 *   remain.
 */
export type EventBuffer = {
  /** Adds an event, coalescing content exposures. Returns the current size. */
  push: (event: AnalyticsEvent) => number;
  /** Removes and returns every buffered event. */
  drain: () => AnalyticsEvent[];
  /** Current number of distinct buffered events. */
  size: () => number;
};

/**
 * Creates an {@link EventBuffer}.
 *
 * @param options - Buffer options.
 * @param options.max - Maximum number of distinct events to retain.
 * @returns A new buffer instance.
 */
export const createEventBuffer = ({ max }: { max: number }): EventBuffer => {
  // Insertion-ordered list of non-coalesced events (page views, conversions).
  let discreteEvents: AnalyticsEvent[] = [];
  // Coalesced content exposures keyed by page/node/locale/variant.
  const exposures = new Map<string, ContentExposureEvent>();

  const size = (): number => discreteEvents.length + exposures.size;

  /** Evicts oldest exposures first, then oldest discrete events. */
  const enforceCap = (): void => {
    while (size() > max && exposures.size > 0) {
      // Map iteration follows insertion order — the first key is the oldest.
      const oldestKey = exposures.keys().next().value as string;
      exposures.delete(oldestKey);
    }
    if (size() > max) {
      discreteEvents = discreteEvents.slice(size() - max);
    }
  };

  const push = (event: AnalyticsEvent): number => {
    if (event.type === 'content_exposure') {
      const key = exposureKey(event);
      const existing = exposures.get(key);

      if (existing) {
        existing.count = (existing.count ?? 1) + (event.count ?? 1);
        existing.t = event.t; // keep the most recent timestamp
      } else {
        exposures.set(key, { ...event, count: event.count ?? 1 });
      }
    } else {
      discreteEvents.push(event);
    }

    enforceCap();

    return size();
  };

  const drain = (): AnalyticsEvent[] => {
    const drained: AnalyticsEvent[] = [
      ...discreteEvents,
      ...exposures.values(),
    ];
    discreteEvents = [];
    exposures.clear();
    return drained;
  };

  return { push, drain, size };
};
